from pathlib import Path
import json,re
parts=json.loads(Path('archive/product-page-parts.json').read_text(encoding='utf-8'))
pages={
'ai-visibility':{'title':'AI visibility tracking','heading':'See where your brand<br>appears in AI answers.','description':'Explore brand mentions, the context around them, and the questions that bring your competitors into an answer.','intro':'AI visibility is about understanding how your brand is represented in generated answers. IcyPluto gives marketing teams a place to investigate those answers alongside the questions, competitors, and report settings behind them.','findings':[('Brand mentions','Inspect whether the brand appears in an answer and read how it is described.'),('Competitor context','Explore which competing brands appear in the same analysis.'),('Question and market context','Interpret results alongside the prompts, region, and available model settings used for the report.')],'workflow':[('Start with a useful question.','Choose a question that reflects a real customer need. Add the brand and competitors you want to investigate.'),('Read the answer.','Review individual responses. A mention count becomes more useful when you understand the surrounding context.'),('Choose a follow-up.','Investigate cited sources, research another question, or bring a finding into content and website work.')],'limits':'An answer is a response to a particular question under particular settings. It is not a fixed ranking for your brand across every AI platform. Model availability and report settings depend on the analysis you run. IcyPluto does not guarantee inclusion or recommendations.','art':'answer'},
'competitor-analysis':{'title':'AI competitor analysis','heading':'Understand who appears<br>alongside your brand.','description':'Use the same questions to investigate your brand and the competitors appearing in AI-generated answers.','intro':'A competitor comparison can reveal questions worth investigating. IcyPluto connects brand analysis with the competitor context inside AI answers, giving teams a concrete starting point for research and planning.','findings':[('Competing brand mentions','Identify the other brands appearing in the responses you are reviewing.'),('Answer context','Read the language surrounding a recommendation or comparison instead of interpreting a number alone.'),('Questions to investigate','Explore where the responses differ across the questions and settings used in your analysis.')],'workflow':[('Choose relevant competitors.','Start with the brands your customers would reasonably compare. Keep the question and market context consistent.'),('Inspect the difference.','Compare the answers and investigate how each brand is described. Look for specific features, use cases, or sources behind the response.'),('Bring evidence into the discussion.','Use the findings to frame a content review, client conversation, or deeper source investigation.')],'limits':'A higher mention count in a set of answers does not establish overall market share, traffic, or revenue. Interpret comparisons within the report context. Responses can change, and no tool controls the model output.','art':'answer'},
'source-research':{'title':'AI citation and source research','heading':'Follow the sources<br>behind an answer.','description':'Investigate cited websites and separate brand-owned content from the publishers, reviews, and other pages in the source trail.','intro':'Source research helps you examine the evidence attached to an AI answer. IcyPluto connects cited-source investigation with brand visibility and research tools, so a team can move from a response to the pages worth inspecting.','findings':[('Cited websites','Explore the sources attached to the answers in your report.'),('Owned and third-party context','Distinguish information on your own site from outside reviews, guides, and publications.'),('Content research','Use source observations to inform the next topic or page you investigate with the product toolkit.')],'workflow':[('Open an answer.','Start with a response relevant to the customer question you are investigating.'),('Inspect the cited page.','Read the actual source. Check whether it supports a product claim, a comparison, or broader background information.'),('Identify the useful next question.','Review your own information, investigate an outside source, or explore a related content opportunity.')],'limits':'A citation does not prove that a source caused every part of an answer or that your brand will be recommended after a page change. Some responses may not include useful citations. Report settings and available evidence affect what you can investigate.','art':'sources'},
'website-audits':{'title':'Website audits with SEOMax','heading':'Find the website issues<br>worth fixing next.','description':'Explore content and technical findings in SEOMax. Bring a clearer website-health picture into your search and AI discovery work.','intro':'Your website is one of the inputs your team can improve. SEOMax provides a place to review website findings, investigate content and technical issues, and plan the next fixes alongside your wider marketing work.','findings':[('Content findings','Review website content issues and information that needs attention.'),('Technical findings','Investigate technical problems and potential barriers to reaching your pages.'),('A starting point for fixes','Use the audit context to prioritize what your team should review and change.')],'workflow':[('Add your website.','Enter the site you want to investigate and review the available audit scope.'),('Review the findings.','Understand the issue and its page context before deciding what to change.'),('Fix and reassess.','Make the appropriate changes, then run a fresh audit to review the updated website.')],'limits':'An audit highlights findings for investigation. It does not guarantee rankings, AI citations, or recommendations. Available findings depend on the website and audit scope. Confirm your required checks in a product walkthrough.','art':'audit'}
}
for slug,data in pages.items():
 head=parts['head'];head=re.sub(r'<title>.*?</title>',f'<title>{data["title"]} | IcyPluto</title>',head);head=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{data["description"]}">',head)
 intro=f'''<section class="detail-hero section-shell"><div><h1>{data['heading']}</h1><p>{data['description']}</p><div class="hero-actions"><a class="product-button" href="/#sample-report">Explore the sample <span>&rarr;</span></a><button class="product-text-link" data-contact="{data['title']} demo">Book a walkthrough <span>&rarr;</span></button></div></div><div class="detail-graphic capability-art art-{data['art']}" aria-hidden="true"><i></i><i></i><i></i><b>{'Your brand' if data['art']=='answer' else ''}</b></div></section>'''
 content=f'''<section class="detail-intro section-shell"><h2>What it helps you understand.</h2><p>{data['intro']}</p></section><section class="detail-findings section-shell"><h2>What you can investigate.</h2><div class="foundation-grid">'''+''.join(f'<article><h3>{title}</h3><p>{text}</p></article>' for title,text in data['findings'])+'''</div></section><section class="detail-workflow section-shell"><h2>From question to follow-up.</h2><ol>'''+''.join(f'<li><h3>{title}</h3><p>{text}</p></li>' for title,text in data['workflow'])+f'''</ol></section><section class="detail-limits section-shell"><h2>Read the context.<br>Know the limits.</h2><p>{data['limits']}</p></section><section class="product-contact section-shell" id="contact"><h2>See it with your<br>own questions in mind.</h2><p>Bring your website and the topics your customers ask about.</p><button class="product-button" data-contact="{data['title']} demo">Book a walkthrough <span>&rarr;</span></button><a class="product-text-link" href="/#sample-report">Explore the sample first <span>&rarr;</span></a></section>'''
 path=Path('platform')/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(head+'<body class="product-site detail-site"><a class="skip" href="#main">Skip to content</a>'+parts['header']+'<main id="main">'+intro+content+'</main>'+parts['footer']+parts['dialogs']+'<script type="module" src="/src/detail.js"></script></body></html>',encoding='utf-8')
head=re.sub(r'<title>.*?</title>','<title>About IcyPluto | A different view of brand discovery</title>',parts['head']);head=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="Learn about IcyPluto, the AI marketing intelligence platform connecting brand visibility, source research, content, and website optimization.">',head)
about='''<section class="detail-hero section-shell"><div><h1>A different view<br>of brand discovery.</h1><p>IcyPluto brings AI visibility research and marketing tools into one workspace.</p><a class="product-button" href="/#sample-report">Explore the product <span>&rarr;</span></a></div><div class="about-orbit" aria-hidden="true"><img src="/assets/icypluto-logo.png" width="90" height="90" alt=""></div></section><section class="detail-intro section-shell"><h2>What we are building.</h2><p>A platform where teams can investigate how AI describes their brand, compare competitors, explore cited sources, and connect those findings to content and website work. The aim is to give marketing conversations a concrete starting point.</p></section><section class="detail-intro section-shell"><h2>Why Pluto?</h2><p>Pluto inspired a visual identity built around exploration and a different perspective. The orbit is a reminder to keep observing: ask a question, investigate the answer, make a useful change, and look again. The product gives that idea a practical workflow.</p></section><section class="detail-findings section-shell"><h2>The work behind the concept.</h2><div class="foundation-grid"><article><h3>Measure</h3><p>Investigate your brand presence in AI-generated answers.</p></article><article><h3>Understand</h3><p>Read the competitor, question, and source context.</p></article><article><h3>Work on it</h3><p>Connect findings to content, structure, and technical work.</p></article></div></section><section class="product-contact section-shell" id="contact"><h2>Bring a question.<br>Take a closer look.</h2><p>Explore the sample workflow or talk through the product with us.</p><button class="product-button" data-contact="About IcyPluto product walkthrough">Book a walkthrough <span>&rarr;</span></button></section>'''
Path('about').mkdir(exist_ok=True);Path('about/index.html').write_text(head+'<body class="product-site detail-site"><a class="skip" href="#main">Skip to content</a>'+parts['header']+'<main id="main">'+about+'</main>'+parts['footer']+parts['dialogs']+'<script type="module" src="/src/detail.js"></script></body></html>',encoding='utf-8')
# Share the working contact/resource dialogs between the home and capability pages.
p=Path('src/main.js');s=p.read_text(encoding='utf-8');start=s.index('// All calls to action');end=s.index('const walkthrough=');contact=s[start:end];Path('src/contact.js').write_text('export function setupContact(){\nconst $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];\n'+contact+'\nreturn {openContact};\n}\n',encoding='utf-8');s=s[:start]+'const {openContact}=setupContact();\n'+s[end:];s="import { setupContact } from './contact.js';\n"+s;p.write_text(s,encoding='utf-8')
print('Created four capability pages, About, and shared dialog module')
